<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Domain;

use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\Holder\ClientIdentityUidAttributeHolder;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityUidVO;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\Holder\ClientIdentityUserAttributeHolder;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityUserVO;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\Holder\ClientIdentityRelyingPartyAttributeHolder;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityRelyingPartyVO;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\Holder\ClientIdentityTrustedClientAttributeHolder;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityTrustedClientVO;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\Holder\ClientIdentityRolesAttributeHolder;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityRolesVO;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\Holder\ClientIdentityVersionAttributeHolder;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject\ClientIdentityVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;

class ClientIdentityAttributes
{
    use ClientIdentityUidAttributeHolder;
    use ClientIdentityUserAttributeHolder;
    use ClientIdentityRelyingPartyAttributeHolder;
    use ClientIdentityTrustedClientAttributeHolder;
    use ClientIdentityRolesAttributeHolder;
    use ClientIdentityVersionAttributeHolder;

    private const array UNSETS = [
      'uid' => 'unsetUid',
      'user' => 'unsetUser',
      'relyingParty' => 'unsetRelyingParty',
      'trustedClient' => 'unsetTrustedClient',
      'roles' => 'unsetRoles',
      'version' => 'unsetVersion',
    ];

    public function build(): ClientIdentity
    {
        $errors = new ConstraintFailList();
        $uid = ClientIdentityUidVO::tryFrom($this->uid, $errors);
        $user = ClientIdentityUserVO::tryFrom($this->user, $errors);
        $relyingParty = ClientIdentityRelyingPartyVO::tryFrom($this->relyingParty, $errors);
        $trustedClient = ClientIdentityTrustedClientVO::tryFrom($this->trustedClient, $errors);
        $roles = ClientIdentityRolesVO::tryFrom($this->roles, $errors);
        $version = ClientIdentityVersionVO::tryFrom($this->version, $errors);
        if ($errors->hasErrors()) {
            throw $errors->asConstraintException();
        }
        \assert($uid !== null);
        \assert($user !== null);
        return new ClientIdentity(
            uid: $uid,
            user: $user,
            relyingParty: $relyingParty,
            trustedClient: $trustedClient,
            roles: $roles,
            version: $version,
        );
    }
    public function withAssertedRules(): ClientIdentityAttributes
    {
        $value = new ClientIdentityAttributes();
        $errorsList = new ConstraintFailList();
        $this->withAssertedUidRules($value, $errorsList);
        $this->withAssertedUserRules($value, $errorsList);
        $this->withAssertedRelyingPartyRules($value, $errorsList);
        $this->withAssertedTrustedClientRules($value, $errorsList);
        $this->withAssertedRolesRules($value, $errorsList);
        $this->withAssertedVersionRules($value, $errorsList);
        if ($errorsList->hasErrors()) {
            throw $errorsList->asConstraintException();
        }
        return $value;
    }
    public function unset(string $field): void
    {
        if (isset(self::UNSETS[$field])) {
            call_user_func([$this, self::UNSETS[$field]]);
        }
    }
    public function withDefaults(): ClientIdentityAttributes
    {
        $this->withDefaultUid();
        $this->withDefaultUser();
        $this->withDefaultRelyingParty();
        $this->withDefaultTrustedClient();
        $this->withDefaultRoles();
        $this->withDefaultVersion();
        return $this;
    }
}
